from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # track used days per (employee, year)
        self._used: dict[tuple[str, int], int] = {}
        # track requests per (employee, year) to avoid double-booking days
        self._booked: dict[tuple[str, int], set[date]] = {}

    def _is_workday(self, d: date) -> bool:
        return d.weekday() < 5 and d not in self.holidays

    def _count_days(self, start: date, end: date) -> int:
        count = 0
        cur = start
        while cur <= end:
            if self._is_workday(cur):
                count += 1
            cur += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date must not be before start date")

        # Count workdays for the requested range, excluding already-booked days
        requested_days = 0
        cur = start
        while cur <= end:
            if self._is_workday(cur):
                key = (employee, cur.year)
                if cur not in self._booked.get(key, set()):
                    requested_days += 1
            cur += timedelta(days=1)

        # Check remaining for each affected year (split at year boundaries)
        # Compute per-year new days
        per_year_needed: dict[int, int] = {}
        cur = start
        while cur <= end:
            if self._is_workday(cur):
                key = (employee, cur.year)
                if cur not in self._booked.get(key, set()):
                    per_year_needed[cur.year] = per_year_needed.get(cur.year, 0) + 1
            cur += timedelta(days=1)

        for year, needed in per_year_needed.items():
            used = self._used.get((employee, year), 0)
            if used + needed > self.days_per_year:
                raise ValueError(
                    f"Insufficient leave remaining for {employee} in {year}: "
                    f"needs {needed}, has {self.days_per_year - used}"
                )

        # Commit the request
        cur = start
        while cur <= end:
            if self._is_workday(cur):
                key = (employee, cur.year)
                booked = self._booked.setdefault(key, set())
                if cur not in booked:
                    booked.add(cur)
                    self._used[key] = self._used.get(key, 0) + 1
            cur += timedelta(days=1)

        return requested_days

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return max(0, self.days_per_year - used)
